    /* Add 'anchor': <anchor>. */

    key = yaml_document_add_scalar(&output_document, NULL,
        (yaml_char_t *)"anchor", -1, YAML_PLAIN_SCALAR_STYLE);
    if (!key) goto document_error;
    value = yaml_document_add_scalar(&output_document, NULL,
